  "tasks": [
    {
      "type": "order",
      "claim_id": "drilling-fluid-impact.c44",
      "question": "Расставьте методы ГИС в порядке возрастания их чувствительности к толщине глинистой корки (от наименьшей к наибольшей).",
      "items": [
        "Электрометрия (индукционный зонд)",
        "Методы малой глубинности (ГГМ, ЯМР)"
      ],
      "explanation": "Глубокое проникновение блокирует электрометрию, а толстая корка блокирует методы малой глубинности, значит корка критичнее для последних."
    },
    {
      "type": "multi",
      "claim_id": "drilling-fluid-impact.c7",
      "question": "В каких типах пород диаметр скважины увеличивается по сравнению с номинальным ($d_c > d_a$)? Выберите все верные варианты.",
      "options": [
        "Плотные сцементированные породы",
        "Глины и аргиллиты",
        "Трещиноватые породы",
        "Растворимые соли"
      ],
      "answer": [
        1,
        2,
        3
      ],
      "explanation": "В плотных породах диаметр номинальный, а в глинах, трещиноватых породах и солях он увеличивается."
    },
    {
      "type": "calc",
      "claim_id": "drilling-fluid-impact.c16",
      "question": "Расскажите величину репрессии ($\\Delta p$), если давление в скважине $p_c$ составляет 45 МПа, а пластовое давление $p_{пл}$ равно 40 МПа.",
      "answer": 5.0,
      "tolerance": 0.1,
      "unit": "МПа",
      "explanation": "Репрессия рассчитывается по формуле $\\Delta p = p_c - p_{пл}$."
    }
  ],
  "card": {
    "front": "Как высокое давление в скважине (репрессия) влияет на качество геофизических данных?",
    "back": "Усиливает проникновение фильтрата в коллектор, что искажает данные глубинных методов электрометрии."
  }
